export PATH=$HOME/.local/bin:$PATH
yarn add -D -E @types/node@22.20.5 2>&1 | tail -1
mkdir -p biome-plugins
cat > biome.json <<'E'
{
  "$schema": "https://biomejs.dev/schemas/2.6.4/schema.json",
  "vcs": { "enabled": true, "clientKind": "git", "useIgnoreFile": true },
  "files": { "ignoreUnknown": false, "includes": ["**", "!**/dist", "!**/node_modules", "!**/.yarn"] },
  "formatter": { "enabled": true, "indentStyle": "tab" },
  "javascript": { "formatter": { "quoteStyle": "double" } },
  "assist": { "enabled": true, "actions": { "source": { "organizeImports": "on" } } },
  "linter": {
    "enabled": true,
    "rules": {
      "preset": "recommended",
      "complexity": { "useArrowFunction": "error" },
      "style": {
        "useImportType": "error",
        "noDefaultExport": "off"
      },
      "suspicious": { "noExplicitAny": "error" }
    }
  },
  "overrides": [
    {
      "includes": ["src/**/*.tsx"],
      "plugins": ["./biome-plugins/component-arrow-function.grit", "./biome-plugins/component-default-export.grit"],
      "linter": { "rules": { "style": { "useComponentExportOnlyModules": "error" } } }
    }
  ]
}
E
cat > biome-plugins/component-arrow-function.grit <<'E'
language js(typescript, jsx)

// Components must be arrow functions: ban `function Foo() { ...<jsx/>... }`
// (including `export default function`) in src/**/*.tsx.
`function $name($params) { $body }` where {
    $body <: contains or { `<$_ />`, `<$_>$_</$_>`, `<>$_</>` },
    register_diagnostic(
        span = $name,
        message = "Components must be arrow functions: use `const Foo = () => ...; export default Foo;` instead of a function declaration.",
        severity = "error"
    )
}
E
cat > biome-plugins/component-default-export.grit <<'E'
language js(typescript, jsx)

// Component files (src/**/*.tsx) must have a default export.
// A file that contains JSX but no `export default` is an error.
`$program` as $p where {
    $p <: contains or { `<$_ />`, `<$_>$_</$_>`, `<>$_</>` },
    $p <: not contains `export default $_`,
    register_diagnostic(
        span = $p,
        message = "Component files must have a default export (`const Foo = () => ...; export default Foo;`).",
        severity = "error"
    )
}
E
cat > src/main.tsx <<'E'
import { createRoot } from "react-dom/client";

const root = document.getElementById("root");
if (root) createRoot(root).render(<p>stub</p>);
E
yarn biome lint . 2>&1 | head -50

